CREATE MATERIALIZED VIEW IF NOT EXISTS {{DB}}.gold_customer_rfm_mv REFRESH EVERY 5 MINUTE TO {{DB}}.gold_customer_rfm (`customer_id` Int32, `customer_name` String, `customer_email` String, `customer_tier` String, `is_vip` Bool, `country` String, `total_orders` UInt64, `total_revenue` Decimal(38, 2), `avg_order_value` Float64, `first_order` DateTime64(6), `last_order` DateTime64(6), `recency_days` Int64, `rfm_segment` String) AS SELECT o.customer_id AS customer_id, o.customer_name AS customer_name, o.customer_email AS customer_email, o.customer_tier AS customer_tier, o.is_vip AS is_vip, o.customer_country AS country, count() AS total_orders, sum(o.total_amount) AS total_revenue, avg(o.total_amount) AS avg_order_value, min(o.created_at) AS first_order, max(o.created_at) AS last_order, dateDiff('day', max(o.created_at), now64()) AS recency_days, multiIf((dateDiff('day', max(o.created_at), now64()) <= 7) AND (sum(o.total_amount) > 500), 'champion', dateDiff('day', max(o.created_at), now64()) <= 7, 'active', (dateDiff('day', max(o.created_at), now64()) <= 30) AND (sum(o.total_amount) > 300), 'loyal', dateDiff('day', max(o.created_at), now64()) <= 30, 'warm', dateDiff('day', max(o.created_at), now64()) <= 90, 'cooling', 'churned') AS rfm_segment FROM {{DB}}.silver_orders AS o WHERE o.status != 'cancelled' GROUP BY o.customer_id, o.customer_name, o.customer_email, o.customer_tier, o.is_vip, o.customer_country;

CREATE MATERIALIZED VIEW IF NOT EXISTS {{DB}}.gold_daily_kpi_mv REFRESH EVERY 1 MINUTE TO {{DB}}.gold_daily_kpi (`dt` Date, `total_revenue` Decimal(38, 2), `total_orders` UInt64, `avg_order_value` Float64, `unique_customers` UInt64, `new_customers` UInt64, `vip_revenue` Decimal(38, 2), `failed_payments` Nullable(UInt64), `payment_failure_rate` Nullable(Float64), `top_category` Nullable(String), `top_country` Nullable(String)) AS SELECT toDate(event_time) AS dt, sum(total_amount) AS total_revenue, count() AS total_orders, avg(total_amount) AS avg_order_value, uniq(customer_id) AS unique_customers, uniqIf(customer_id, toDate(event_time) = today()) AS new_customers, sumIf(total_amount, (customer_id IN (SELECT id FROM {{DB}}.public_customers AS pc FINAL WHERE (pc.is_vip = 1) AND (pc._peerdb_is_deleted = 0)))) AS vip_revenue, (SELECT count() FROM {{DB}}.payment_events WHERE (toDate(event_time) = dt) AND (status = 'failed')) AS failed_payments, (SELECT countIf(status = 'failed') / greatest(count(), 1) FROM {{DB}}.payment_events WHERE toDate(event_time) = dt) AS payment_failure_rate, (SELECT category FROM {{DB}}.order_events WHERE toDate(event_time) = dt GROUP BY category ORDER BY sum(total_amount) DESC LIMIT 1) AS top_category, (SELECT country FROM {{DB}}.order_events WHERE toDate(event_time) = dt GROUP BY country ORDER BY sum(total_amount) DESC LIMIT 1) AS top_country FROM {{DB}}.order_events WHERE event_time >= (today() - 30) GROUP BY dt;

CREATE MATERIALIZED VIEW IF NOT EXISTS {{DB}}.gold_funnel_hourly_mv REFRESH EVERY 1 MINUTE TO {{DB}}.gold_funnel_hourly (`dt` Date, `hour` UInt8, `country` String, `device` String, `page_views` UInt64, `cart_adds` UInt64, `checkouts` UInt64, `purchases` UInt64, `cart_rate` Float64, `checkout_rate` Float64, `purchase_rate` Float64) AS SELECT pv.dt AS dt, pv.hour AS hour, pv.country AS country, pv.device AS device, pv.cnt AS page_views, coalesce(ca.cnt, 0) AS cart_adds, coalesce(co.cnt, 0) AS checkouts, coalesce(pu.cnt, 0) AS purchases, if(pv.cnt > 0, coalesce(ca.cnt, 0) / pv.cnt, 0) AS cart_rate, if(coalesce(ca.cnt, 0) > 0, coalesce(co.cnt, 0) / ca.cnt, 0) AS checkout_rate, if(coalesce(co.cnt, 0) > 0, coalesce(pu.cnt, 0) / co.cnt, 0) AS purchase_rate FROM (SELECT toDate(event_time) AS dt, toHour(event_time) AS hour, country, toString(device) AS device, count() AS cnt FROM {{DB}}.page_events WHERE event_time >= (today() - 7) GROUP BY dt, hour, country, device) AS pv LEFT JOIN (SELECT toDate(event_time) AS dt, toHour(event_time) AS hour, country, toString(device) AS device, count() AS cnt FROM {{DB}}.cart_events WHERE event_time >= (today() - 7) GROUP BY dt, hour, country, device) AS ca USING (dt, hour, country, device) LEFT JOIN (SELECT toDate(event_time) AS dt, toHour(event_time) AS hour, country, toString(device) AS device, count() AS cnt FROM {{DB}}.checkout_events WHERE event_time >= (today() - 7) GROUP BY dt, hour, country, device) AS co USING (dt, hour, country, device) LEFT JOIN (SELECT toDate(event_time) AS dt, toHour(event_time) AS hour, country, toString(device) AS device, count() AS cnt FROM {{DB}}.order_events WHERE event_time >= (today() - 7) GROUP BY dt, hour, country, device) AS pu USING (dt, hour, country, device);

CREATE MATERIALIZED VIEW IF NOT EXISTS {{DB}}.gold_vip_dashboard_mv REFRESH EVERY 5 MINUTE TO {{DB}}.gold_vip_dashboard (`customer_id` Int32, `customer_name` String, `customer_email` String, `tier` String, `country` String, `total_orders` UInt64, `total_revenue` Decimal(38, 2), `failed_payments` UInt64, `last_order_at` DateTime64(6), `last_failure_reason` String, `risk_level` String) AS SELECT c.id AS customer_id, c.full_name AS customer_name, c.email AS customer_email, c.tier AS tier, c.country AS country, count(o.order_id) AS total_orders, sum(o.total_amount) AS total_revenue, countIf(p.payment_status = 'failed') AS failed_payments, max(o.created_at) AS last_order_at, argMax(p.failure_reason, p.updated_at) AS last_failure_reason, multiIf(countIf(p.payment_status = 'failed') >= 3, 'critical', countIf(p.payment_status = 'failed') >= 1, 'at_risk', 'healthy') AS risk_level FROM {{DB}}.silver_customers AS c LEFT JOIN {{DB}}.silver_orders AS o ON o.customer_id = c.id LEFT JOIN {{DB}}.silver_payments AS p ON p.order_id = o.order_id WHERE c.is_vip = 1 GROUP BY c.id, c.full_name, c.email, c.tier, c.country;

CREATE MATERIALIZED VIEW IF NOT EXISTS {{DB}}.silver_customers_mv REFRESH EVERY 30 SECOND TO {{DB}}.silver_customers (`id` Int32, `email` String, `full_name` String, `country` String, `tier` String, `is_vip` Bool, `created_at` DateTime64(6)) AS SELECT id, email, full_name, country, tier, is_vip, created_at FROM {{DB}}.public_customers FINAL WHERE _peerdb_is_deleted = 0;

CREATE MATERIALIZED VIEW IF NOT EXISTS {{DB}}.silver_orders_mv REFRESH EVERY 30 SECOND TO {{DB}}.silver_orders (`order_id` Int32, `customer_id` Int32, `customer_name` String, `customer_email` String, `customer_country` String, `customer_tier` String, `is_vip` Bool, `status` String, `total_amount` Decimal(10, 2), `payment_method` String, `country` String, `channel` String, `created_at` DateTime64(6), `items_count` UInt64, `items_revenue` Decimal(38, 2)) AS SELECT o.id AS order_id, o.customer_id AS customer_id, c.full_name AS customer_name, c.email AS customer_email, c.country AS customer_country, c.tier AS customer_tier, c.is_vip AS is_vip, o.status AS status, o.total_amount AS total_amount, o.payment_method AS payment_method, o.country AS country, o.channel AS channel, o.created_at AS created_at, count(oi.id) AS items_count, sum(oi.total_price) AS items_revenue FROM {{DB}}.public_orders AS o FINAL LEFT JOIN {{DB}}.public_customers AS c FINAL ON (c.id = o.customer_id) AND (c._peerdb_is_deleted = 0) LEFT JOIN {{DB}}.public_order_items AS oi FINAL ON (oi.order_id = o.id) AND (oi._peerdb_is_deleted = 0) WHERE o._peerdb_is_deleted = 0 GROUP BY o.id, o.customer_id, c.full_name, c.email, c.country, c.tier, c.is_vip, o.status, o.total_amount, o.payment_method, o.country, o.channel, o.created_at;

CREATE MATERIALIZED VIEW IF NOT EXISTS {{DB}}.silver_payments_mv REFRESH EVERY 30 SECOND TO {{DB}}.silver_payments (`order_id` Int32, `payment_status` String, `provider` String, `failure_reason` String, `customer_id` Int32, `order_amount` Decimal(10, 2), `payment_method` String, `order_country` String, `order_channel` String, `order_status` String, `updated_at` DateTime64(6)) AS SELECT p.order_id, p.status AS payment_status, p.provider, p.failure_reason, o.customer_id, o.total_amount AS order_amount, o.payment_method, o.country AS order_country, o.channel AS order_channel, o.status AS order_status, p.updated_at FROM {{DB}}.public_payment_status_current AS p FINAL INNER JOIN {{DB}}.public_orders AS o FINAL ON (o.id = p.order_id) AND (o._peerdb_is_deleted = 0) WHERE p._peerdb_is_deleted = 0;

CREATE MATERIALIZED VIEW IF NOT EXISTS {{DB}}.silver_products_mv REFRESH EVERY 30 SECOND TO {{DB}}.silver_products (`id` Int32, `sku` String, `name` String, `category` String, `price` Decimal(10, 2), `inventory_available` Int32, `created_at` DateTime64(6)) AS SELECT id, sku, name, category, price, inventory_available, created_at FROM {{DB}}.public_products FINAL WHERE _peerdb_is_deleted = 0;
